STORY = [('chun_yuqiao', '我已经做了打持久战的准备，十二歌王开播全靠你们自己了。', 'I am prepared for drawn-out talks abroad, so launching Twelve Singers rests entirely on your shoulders.', [(755, '我已经做了'), (756, '持久战的准备'), (758, '全靠你们自己了')], ''), ('chun_yuqiao', '有什么情况你随时给我打电话，不要管时差的事，我在美国会二十四小时开机。', 'Call me anytime something comes up regardless of the time difference; my phone will stay on twenty-four hours a day.', [(765, '有什么情况'), (766, '你随时给我打电话'), (767, '不要管时差的事'), (768, '我在美国会二十四小时开机')], ''), ('chun_yuqiao', '你怎么来了？我今天要去美国出差。', "What brings you to the office? I'm flying overseas on business today.", [(778, '你怎么来了'), (780, '要去美国出差')], ''), ('xin_huimei', '来看你啊！我可是人生第一次尝试传说中的办公室恋爱。', 'I came to see you! This is my very first time trying out a legendary office romance.', [(779, '来看你啊'), (781, '我可是人生第一次尝试'), (782, '传说中的办公室恋爱')], ''), ('chun_yuqiao', '不好意思啊，我应该在出差之前多找时间陪陪你的，我疏忽了。', "I'm sorry — I should have carved out more time to spend with you before my trip; that was careless of me.", [(786, '不好意思啊'), (788, '在出差之前'), (789, '多找时间陪陪你的'), (790, '我疏忽了')], ''), ('xin_huimei', '你这个人呀是够疏忽的，就连个男朋友的人影都看不到。', "You certainly are careless! After going public in grand style, I haven't even caught sight of my boyfriend.", [(791, '你这个人呀'), (792, '是够疏忽的'), (795, '就连个男朋友的人影'), (796, '都看不到')], ''), ('chun_yuqiao', '我其实不太擅长谈恋爱。那不是应该的吗？这是我作为男朋友的义务啊。', "Truthfully, I'm not very skilled at romance — isn't taking your words seriously my duty as your boyfriend?", [(799, '我其实就是'), (800, '不太擅长谈恋爱'), (806, '那不是应该的吗'), (807, '这是我作为男朋友的义务啊')], ''), ('xin_huimei', '义务？跟我谈恋爱，用不着拿出尽义务的心态。', "Duty? Dating me doesn't call for the mindset of fulfilling an obligation!", [(808, '义务'), (810, '用不着拿出'), (811, '尽义务的心态')], ''), ('xin_huimei', '喜欢我的人是因为我的魅力，爱我的人是因为我的心，你不需要做出以身相许的状态。', "People like me for my charm and love me for my heart; you don't need to act like you owe me your life.", [(812, '喜欢我的人'), (813, '我的魅力'), (814, '爱我的人'), (814, '我的心'), (815, '你不需要做出以身相许')], ''), ('xin_huimei', '好了，开个玩笑。一路平安！', "Alright, I'm only teasing you. Have a safe flight!", [(824, '好了 开个玩笑'), (825, '路平安')], ''), ('bu_xiaogu', '杰瑞哥交代过我了，您在美国日程上要是有什么改变随时通知我，我二十四小时开机。', 'Her manager briefed me — if anything changes in your schedule abroad, notify me anytime; my phone stays on round the clock.', [(829, '交代过我了'), (830, '您在美国日程上'), (831, '要是有什么改变'), (832, '随时通知我'), (833, '我二十四小时开机')], ''), ('chun_yuqiao', '以后日程上的事，你不用管了。', "From now on, you don't need to concern yourself with my schedule.", [(834, '以后日程上的事'), (835, '你不用管了')], '')]
WALK = [(0, None, "'I am prepared for drawn-out talks abroad, so launching Twelve Singers rests entirely on your shoulders.'"), (1, None, "'Call me anytime something comes up regardless of the time difference; my phone will stay on twenty-four hours a day.'"), (2, None, '"What brings you to the office? I\'m flying overseas on business today."'), (3, None, "'I came to see you! This is my very first time trying out a legendary office romance.'"), (4, None, '"I\'m sorry — I should have carved out more time to spend with you before my trip; that was careless of me."'), (5, None, '"You certainly are careless! After going public in grand style, I haven\'t even caught sight of my boyfriend."'), (6, None, '"Truthfully, I\'m not very skilled at romance — isn\'t taking your words seriously my duty as your boyfriend?"'), (7, None, '"Duty? Dating me doesn\'t call for the mindset of fulfilling an obligation!"'), (8, None, '"People like me for my charm and love me for my heart; you don\'t need to act like you owe me your life."'), (9, None, '"Alright, I\'m only teasing you. Have a safe flight!"'), (10, None, "'Her manager briefed me — if anything changes in your schedule abroad, notify me anytime; my phone stays on round the clock.'"), (11, None, '"From now on, you don\'t need to concern yourself with my schedule."')]
